SELECT 
  ?director ?directorOccupation ?kordaOccupation WHERE {
  ?film a dbo:Film ;
        rdfs:label "Little Children"@en ;
        dbo:releaseDate "2006"^^xsd:gYear ;
        dbo:director ?director .
  OPTIONAL { ?director dbo:occupation ?directorOccupation . }

  ?korda rdfs:label "Zoltan Korda"@en .
  OPTIONAL { ?korda dbo:occupation ?kordaOccupation . }

  FILTER(
    ?directorOccupation IN (dbo:FilmDirector, dbo:FilmProducer, dbo:Screenwriter, dbo:Actor) &&
    ?kordaOccupation IN (dbo:FilmDirector, dbo:FilmProducer, dbo:Screenwriter, dbo:Actor)
  )
}
LIMIT 1

SELECT ?show ?host ?numberOfShowsHosted WHERE {
  ?appearance dbo:starring dbr:Paul_Melba ;
              dbo:series ?show .
  ?show dbo:country dbr:United_Kingdom ;
        dbo:presenter ?host .
  ?host dbo:numberOfShowsHosted ?numberOfShowsHosted .
  FILTER(?numberOfShowsHosted = 23)
}

SELECT ?show ?host ?numberOfShowsHosted WHERE {
  ?show rdf:type dbo:TelevisionShow ;
        dbo:country dbr:United_Kingdom ;
        dbo:starring dbr:Paul_Melba ;
        dbo:presenter ?host .
  ?host dbo:numberOfShowsHosted ?numberOfShowsHosted .
  FILTER(?numberOfShowsHosted = 23)
} LIMIT 10

SELECT ?cemetery ?cemeteryName ?parkName WHERE {
  ?person a schema:Person ;
          schema:name "George W. Wallace" ;
          dbo:profession "professional golfer"@en ;
          dbo:deathPlace ?cemetery .
  ?cemetery a dbo:Cemetery ;
            rdfs:label ?cemeteryName .
  ?park a dbo:NationalPark ;
        rdfs:label ?parkName ;
        dbo:location ?cemetery .
  FILTER(CONTAINS(LCASE(?parkName), "golden gate national recreation area"))
} LIMIT 1

